CREATE TABLE historial_asignaciones (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_pedido BIGINT NOT NULL, conductor_anterior_id BIGINT, conductor_nuevo_id BIGINT NOT NULL, operador_id BIGINT, accion VARCHAR(20) NOT NULL, motivo VARCHAR(500), fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notificaciones_conductor (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_usuario_conductor BIGINT NOT NULL, id_pedido BIGINT NOT NULL, mensaje VARCHAR(255) NOT NULL, fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, leida BOOLEAN NOT NULL DEFAULT FALSE);
